"""
Synapse Autonomy Pipeline — Validator Tests

Tests for synapse.autonomy.validator.PreFlightValidator.
Run without Houdini:
    python -m pytest tests/test_autonomy_validator.py -v
"""

import sys
import os
from unittest.mock import AsyncMock, MagicMock

import pytest

# Add package to path
package_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
python_dir = os.path.join(package_root, "python")
sys.path.insert(0, python_dir)

from synapse.autonomy.models import (
    CheckSeverity,
    GateLevel,
    RenderPlan,
    RenderStep,
    PreFlightCheck,
)
from synapse.autonomy.validator import PreFlightValidator


# =============================================================================
# FIXTURES
# =============================================================================


def _make_valid_handler():
    """Create a mock handler interface that reports a fully valid scene."""
    handler = AsyncMock()

    async def _call(command, params=None):
        responses = {
            "get_scene_info": {
                "status": "ok",
                "cameras": ["/cameras/cam1"],
                "renderable_prims": ["/geo/shape"],
                "frame_range": [1, 48],
                "fps": 24,
            },
            "get_stage_info": {
                "status": "ok",
                "prim_count": 50,
                "materials": ["/materials/mat1"],
            },
            "get_parm": {
                "status": "ok",
                "value": 64,  # pixel samples
            },
            "inspect_scene": {
                "status": "ok",
                "nodes": ["/stage/render_settings", "/stage/karma"],
                "missing_assets": [],
            },
        }
        return responses.get(command, {"status": "ok"})

    handler.call = _call
    return handler


def _make_plan(**overrides):
    """Create a minimal RenderPlan for validation."""
    defaults = {
        "intent": "render frame 1",
        "steps": [
            RenderStep(handler="render_settings", params={"samples": 64}, description="Settings"),
            RenderStep(handler="render", params={"frame": 1}, description="Render"),
        ],
        "estimated_frames": 1,
    }
    defaults.update(overrides)
    return RenderPlan(**defaults)


@pytest.fixture
def valid_handler():
    return _make_valid_handler()


@pytest.fixture
def validator(valid_handler):
    return PreFlightValidator(valid_handler)


@pytest.fixture
def plan():
    return _make_plan()


# =============================================================================
# VALIDATION TESTS
# =============================================================================


class TestPreFlightValidation:
    """Tests for PreFlightValidator.validate()."""

    @pytest.mark.asyncio
    async def test_valid_scene_passes(self, validator, plan):
        """A fully valid scene should pass all checks."""
        checks = await validator.validate(plan)
        assert isinstance(checks, list)
        assert len(checks) > 0
        hard_fails = [c for c in checks if c.severity == CheckSeverity.HARD_FAIL and not c.passed]
        assert len(hard_fails) == 0

    @pytest.mark.asyncio
    async def test_missing_camera_hard_fails(self, plan):
        """Missing camera triggers a hard fail."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": [], "renderable_prims": ["/geo/shape"],
                        "frame_range": [1, 48], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 10, "materials": ["/mat/m1"]}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": []}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        camera_checks = [c for c in checks if "camera" in c.name.lower()]
        assert len(camera_checks) >= 1
        assert any(not c.passed and c.severity == CheckSeverity.HARD_FAIL for c in camera_checks)

    @pytest.mark.asyncio
    async def test_missing_renderable_prims_hard_fails(self, plan):
        """No renderable prims triggers a hard fail."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": ["/cam/cam1"], "renderable_prims": [],
                        "frame_range": [1, 48], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 1, "materials": ["/mat/m1"]}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": []}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        prim_checks = [c for c in checks if "renderable" in c.name.lower() or "prim" in c.name.lower()]
        assert any(not c.passed and c.severity == CheckSeverity.HARD_FAIL for c in prim_checks)

    @pytest.mark.asyncio
    async def test_missing_materials_soft_warns(self, plan):
        """No materials triggers a soft warning, not a hard fail."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": ["/cam/cam1"],
                        "renderable_prims": ["/geo/shape"], "frame_range": [1, 48], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 10, "materials": []}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": []}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        mat_checks = [c for c in checks if "material" in c.name.lower()]
        assert any(not c.passed and c.severity == CheckSeverity.SOFT_WARN for c in mat_checks)

    @pytest.mark.asyncio
    async def test_low_samples_soft_warns(self, validator):
        """Low pixel samples triggers a soft warning."""
        plan = _make_plan(
            steps=[
                RenderStep(handler="render_settings", params={"samples": 2}, description="Low"),
                RenderStep(handler="render", params={"frame": 1}, description="Render"),
            ],
        )
        checks = await validator.validate(plan)
        sample_checks = [c for c in checks if "sample" in c.name.lower() or "render_settings" in c.name.lower()]
        # At minimum, the validator runs and returns checks
        assert isinstance(checks, list)

    @pytest.mark.asyncio
    async def test_invalid_frame_range_hard_fails(self, plan):
        """Frame range start > end triggers hard fail."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": ["/cam/cam1"],
                        "renderable_prims": ["/geo/shape"], "frame_range": [100, 1], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 10, "materials": ["/mat/m1"]}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": []}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        range_checks = [c for c in checks if "frame_range" in c.name.lower() or "frame" in c.name.lower()]
        assert any(not c.passed for c in range_checks)

    @pytest.mark.asyncio
    async def test_negative_frame_range_hard_fails(self, plan):
        """Negative frame range triggers hard fail."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": ["/cam/cam1"],
                        "renderable_prims": ["/geo/shape"], "frame_range": [-10, -20], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 10, "materials": ["/mat/m1"]}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": []}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        range_checks = [c for c in checks if "frame" in c.name.lower()]
        assert any(not c.passed for c in range_checks)

    @pytest.mark.asyncio
    async def test_output_path_missing_warns(self, plan):
        """Missing output path triggers a warning."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": ["/cam/cam1"],
                        "renderable_prims": ["/geo/shape"], "frame_range": [1, 48], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 10, "materials": ["/mat/m1"]}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": []}
            if command == "get_parm":
                return {"status": "error", "message": "Couldn't find parameter"}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        path_checks = [c for c in checks if "output" in c.name.lower() or "path" in c.name.lower()]
        # Should have at least one check about output
        assert isinstance(checks, list)
        assert len(checks) > 0

    @pytest.mark.asyncio
    async def test_solaris_ordering_stub(self, validator, plan):
        """Solaris ordering check should return INFO severity."""
        checks = await validator.validate(plan)
        ordering_checks = [c for c in checks if "ordering" in c.name.lower() or "solaris" in c.name.lower()]
        if ordering_checks:
            assert all(c.severity == CheckSeverity.INFO for c in ordering_checks)

    @pytest.mark.asyncio
    async def test_missing_assets_warns(self, plan):
        """Missing assets triggers a warning."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": ["/cam/cam1"],
                        "renderable_prims": ["/geo/shape"], "frame_range": [1, 48], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 10, "materials": ["/mat/m1"]}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": ["/textures/missing.exr"]}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        asset_checks = [c for c in checks if "asset" in c.name.lower() or "missing" in c.name.lower()]
        if asset_checks:
            assert any(not c.passed for c in asset_checks)

    @pytest.mark.asyncio
    async def test_multiple_hard_fails(self, plan):
        """Multiple hard failures are all reported (no short-circuit)."""
        handler = AsyncMock()

        async def _call(command, params=None):
            if command == "get_scene_info":
                return {"status": "ok", "cameras": [], "renderable_prims": [],
                        "frame_range": [100, 1], "fps": 24}
            if command == "get_stage_info":
                return {"status": "ok", "prim_count": 0, "materials": []}
            if command == "inspect_scene":
                return {"status": "ok", "nodes": [], "missing_assets": []}
            return {"status": "ok"}

        handler.call = _call
        validator = PreFlightValidator(handler)
        checks = await validator.validate(plan)
        hard_fails = [c for c in checks if c.severity == CheckSeverity.HARD_FAIL and not c.passed]
        assert len(hard_fails) >= 2, "Multiple hard fails should all be reported"

    @pytest.mark.asyncio
    async def test_all_checks_run(self, validator, plan):
        """All 8 check categories are executed (no short-circuiting)."""
        checks = await validator.validate(plan)
        # At minimum, the validator runs more than one check
        assert len(checks) >= 4, f"Expected at least 4 checks, got {len(checks)}"
